  id String @id @db.Uuid

  /// Article's {@link economic_political_board_articles.id}. Required foreign
  /// key reference to the article this tag belongs to.
  article_id String @db.Uuid

  /// Tag's {@link economic_political_board_tags.id}. Required foreign key
  /// reference to the tag that categorizes the article.
  tag_id String @db.Uuid

  /// Timestamp when this article-tag relationship was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this article-tag relationship was last modified.
  updated_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  article economic_political_board_articles @relation(fields: [article_id], references: [id], onDelete: Cascade)
  tag     economic_political_board_tags     @relation(fields: [tag_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@unique([article_id, tag_id])
  @@index([article_id])
  @@index([tag_id])
}

schemas.schema-07-banrecords.prisma:
/// Records of user bans issued by administrators, including the ban reason,
