  // 3. Member creates article with tags and attachments
  const tagsInput: string[] = ["politics", "economy"];
  const attachments: IEconomicPoliticalBoardAttachment.ICreate[] = [
    {
      file_url: "https://example.com/images/chart.png",
      file_name: "chart.png",
      file_type: "image",
