  TestValidator.notEquals(
    "has valid ID",
    attachment.id,
    "00000000-0000-0000-0000-000000000000",
  );
  TestValidator.predicate(
    "has valid created_at",
    attachment.created_at !== undefined,
  );
  TestValidator.predicate(
    "article title matches",
    attachment.article.title === article.title,
  );
}

