  // 11. Test sorting by promoted_at ascending
  const sortedByPromotedAtAsc =
    await api.functional.economicPoliticalBoard.admin.roles.index(
      adminConnection,
      {
        body: { sortBy: "promoted_at", sortOrder: "asc" },
      },
