@Controller("/economicPoliticalBoard/auth/guest")
export class EconomicpoliticalboardAuthGuestController {
  /**
   * User registration endpoint for the Economic/Political Discussion Board system. This operation creates a new user account by validating the provided email address format and checking for duplicates in the User table's email field, which has a unique constraint. The password is securely hashed and stored in the passwordHash field of the User table. Upon successful registration, the system generates JWT tokens (access and refresh) that enable the newly registered user to authenticate and access protected resources.
   *
   * The registration process enforces the uniqueness constraint on the email field defined in the database schema. If an email already exists in the User table, the operation returns a validation error. The newly created user record includes the hashed password and is initially marked as not banned (isBanned = false). The system automatically creates an associated Profile record with a default display name and bio.
   *
   * Upon successful registration, the response includes both access and refresh tokens. The access token has a shorter expiration period (typically 15-30 minutes) for API requests, while the refresh token has a longer validity period (typically 7 days) for token renewal, as specified in the Token Expiration Policy (section 35). Users can use the access token immediately after registration to perform authenticated operations such as creating articles or comments.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Registration credentials for the Economic/Political Discussion Board system
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor guest
   * @x-autobe-specification Service layer validates email format and uniqueness against User.email field. Password is hashed using bcrypt or similar algorithm and stored in User.passwordHash. New user record is created with email and passwordHash. User is marked as isBanned=false. Session tokens (access and refresh) are generated using JWT with user identity and expiration. Refresh token has longer expiration (e.g., 7 days) per section 35 Token Expiration Policy. Authorized response includes both tokens. After successful registration, user can immediately use access token for authenticated operations.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEconomicPoliticalBoardGuest.IJoin,
  ): Promise<IEconomicPoliticalBoardGuest.IAuthorized> {
    try {
      return await postEconomicPoliticalBoardAuthGuestJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Token refresh endpoint for the Economic/Political Discussion Board system. This operation validates the provided refresh token against the authentication service's token store and regenerates a new access token for the user. The refresh token is issued during the initial registration (join) operation and has a longer validity period (typically 7 days) as specified in the Token Expiration Policy (section 35).
   *
   * The system validates the refresh token's cryptographic signature and checks whether it has expired. If the token is valid and not expired, a new access token is generated with the user's identity embedded in the JWT claims. The new access token has a shorter expiration period (typically 15-30 minutes) and can be used immediately for authenticated API requests. Depending on the security configuration, the refresh token may be rotated (a new refresh token is issued) or retained for subsequent refresh requests.
   *
   * This operation is stateless and does not modify the User table directly. The token validation is performed entirely in memory using the cryptographic keys. If the refresh token is invalid, expired, or has been revoked, the operation returns an authentication error, and the user must re-register or re-authenticate.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Refresh token credentials for token renewal
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor guest
   * @x-autobe-specification Service layer validates the refresh token format and signature. Checks if the token is expired by comparing the expiration claim against current time. If valid, generates new access token with user identity. Refresh token may be rotated (new refresh token issued) or retained based on security policy. User's lastRefreshedAt is updated if applicable. Returns new access token and potentially new refresh token. Token expiration is enforced per section 35 Token Expiration Policy.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IEconomicPoliticalBoardGuest.IRefresh,
  ): Promise<IEconomicPoliticalBoardGuest.IAuthorized> {
    try {
      return await postEconomicPoliticalBoardAuthGuestRefresh({
        body,
      });
