@Controller("/economicPoliticalBoard/auth/member")
export class EconomicpoliticalboardAuthMemberController {
  /**
   * Registration operation creates a new member account in the Economic/Political Discussion Board system. This endpoint accepts an email address and password, validates them against business rules, creates the corresponding User and Profile records, and returns authentication tokens for immediate use.
   *
   * The email address is validated for proper format and checked against the User table's unique constraint to prevent duplicate registrations. The provided password is hashed using a secure algorithm (bcrypt or argon2) and stored in the passwordHash field of the User table. The newly created account begins with isBanned set to false, with no ban reason or ban timestamp recorded.
   *
   * Upon successful registration, a Profile record is automatically created linked to the new User via the userId foreign key, containing the display name and optional bio provided during registration. The system returns a JWT access token and refresh token, enabling the new member to immediately access protected API endpoints without requiring a separate login step.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Registration credentials for new member account
   * @x-autobe-authorization-type join
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Create new member account by: 1) Validate email format and uniqueness against User.email (unique constraint) 2) Hash password using bcrypt/argon2 and store as passwordHash 3) Create User record with isBanned=false, null ban fields 4) Create Profile record with user-generated displayName and optional bio 5) Return JWT tokens (accessToken, refreshToken) with member role 6) Log account creation timestamp. Email uniqueness enforced at database level with unique constraint. Password stored as hash only - never plaintext. Account starts active (isBanned=false).
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("join")
  public async join(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEconomicPoliticalBoardMember.IJoin,
  ): Promise<IEconomicPoliticalBoardMember.IAuthorized> {
    try {
      return await postEconomicPoliticalBoardAuthMemberJoin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Login operation authenticates an existing member by validating their email and password credentials against the stored User records in the database. This endpoint receives the member's email and password, performs secure credential verification, and returns JWT tokens for accessing protected resources.
   *
   * The system queries the User table by email address to locate the corresponding account. If found, it verifies the provided password against the stored passwordHash using a secure comparison algorithm (bcrypt or argon2). The account's isBanned field is checked to ensure the member is not suspended; if banned, the login is rejected and the ban details (reason and timestamp from banReason and banAt fields) are optionally returned for user notification.
   *
   * Upon successful validation, the system generates a new access token with member role claims and a refresh token for token rotation. The access token includes the member's ID and role, enabling API endpoints to identify and authorize requests. Both tokens are returned in the response, allowing the client to immediately access protected resources without additional authentication steps.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Login credentials for existing member account
   * @x-autobe-authorization-type login
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Login operation validates member credentials: 1) Query User table by email, verify record exists 2) Verify password matches passwordHash using bcrypt/argon2 verify 3) Check isBanned=false; if banned, reject with banReason details from banReason and banAt fields 4) Generate new JWT access token with member role and expiration 5) Generate new refresh token for token rotation 6) Return both tokens. Failed attempts logged for security monitoring. Banned users cannot login - must contact administrator for account review.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("login")
  public async login(
    @Ip()
    ip: string,
    @TypedBody()
    body: IEconomicPoliticalBoardMember.ILogin,
  ): Promise<IEconomicPoliticalBoardMember.IAuthorized> {
    try {
      return await postEconomicPoliticalBoardAuthMemberLogin({
        ip,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Token refresh operation renews the member's access token using a valid refresh token, enabling seamless continued access to protected resources without requiring re-authentication. This endpoint accepts a refresh token, validates its integrity and expiration, and issues a new pair of access and refresh tokens.
   *
   * The system decodes the provided refresh token and verifies its cryptographic signature and expiration timestamp against the JWT standards. If the token is valid and not expired, the system generates a new access token with the same member role claims and a new refresh token. This token rotation mechanism enhances security by preventing token reuse attacks - each refresh operation invalidates the previous refresh token and issues a new one.
   *
   * The member's authentication state is maintained throughout this process, allowing continuous access to API endpoints without requiring the member to re-enter their email and password. If the refresh token is invalid, expired, or has been revoked, the operation fails and the member must perform a new login to obtain fresh tokens.
   *
   * @setHeader token.access Authorization
   *
   * @param connection
   * @param body Refresh token for renewing access credentials
   * @x-autobe-authorization-type refresh
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Token refresh operation validates existing refresh token: 1) Decode and verify refresh token signature and expiration 2) If valid, generate new access token with member role 3) Generate new refresh token (token rotation) 4) Store new refresh token hash (optional for rotation tracking) 5) Return new token pair. Invalid or expired refresh tokens are rejected. Token rotation prevents token reuse attacks. Member remains authenticated without re-entering credentials.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("refresh")
  public async refresh(
    @TypedBody()
    body: IEconomicPoliticalBoardMember.IRefresh,
  ): Promise<IEconomicPoliticalBoardMember.IAuthorized> {
    try {
      return await postEconomicPoliticalBoardAuthMemberRefresh({
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

