import { GuestAuth } from "../../../../../decorators/GuestAuth";
import { GuestPayload } from "../../../../../decorators/payload/GuestPayload";
import { patchEconomicPoliticalBoardGuestArticlesTags } from "../../../../../providers/patchEconomicPoliticalBoardGuestArticlesTags";

@Controller("/economicPoliticalBoard/guest/articles/tags")
export class EconomicpoliticalboardGuestArticlesTagsController {
  /**
   * Retrieve a filtered and paginated list of articles organized by topic tags.
   *
   * This operation enables users to discover articles associated with specific tags, facilitating cross-section content discovery and topic-based browsing. Support comprehensive filtering by tag names, with optional pagination and sorting capabilities.
   *
   * Articles returned include summary information optimized for list displays, including title, author, creation timestamp, and associated tags. The operation supports multiple tag filtering modes including exact match and partial search.
   *
   * Security considerations: Only articles visible to the requesting actor (guest, member, or admin) will be returned. Banned users cannot access this operation.
   *
   * @param connection
   * @param body Search criteria for articles by tags
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor guest
   * @x-autobe-specification Query economic_political_board_articles table with JOINs to economic_political_board_article_tags and economic_political_board_tags for tag filtering.
   *
   * Apply filters:
   * - tagNames: array of tag names to filter by (any/all matching)
   * - tagNameExact: exact tag name match
   * - query: search in article title and content
   * - sectionId: optional section filter
   * - sortBy: 'newest', 'oldest', or 'popular'
   * - page: 1-based page number
   * - limit: items per page (max 100)
   *
   * Join with economic_political_board_tags on tag name equality.
   *
   * Filter articles based on actor visibility rules: guests see published articles, members see published articles, admins see all articles.
   *
   * Exclude articles from deleted sections.
   *
   * Return cursor-based pagination or offset-based pagination with total count.
   *
   * Sort results by createdAt descending for 'newest', ascending for 'oldest', or by commentCount descending for 'popular'.
   *
   * Validate tag names exist in economic_political_board_tags before filtering.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @GuestAuth()
    guest: GuestPayload,
    @TypedBody()
    body: IEconomicPoliticalBoardArticle.ITagSearch,
  ): Promise<IPageIEconomicPoliticalBoardArticle.ISummary> {
    try {
      return await patchEconomicPoliticalBoardGuestArticlesTags({
        guest,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}

